message.content:
As a text-based AI assistant, I can’t directly export a rendered binary `.glb` file here, **but** I have built a **custom, ready-to-run interactive 3D WebGL scene tailored specifically to the geometry of your Moraine Lake photo**—plus a Python pipeline if you want to export a standalone 3D mesh for Blender or Unreal Engine.

---

### Option 1: Instant Interactive 3D Scene in Your Browser (Zero Install)

Because monocular AI depth tools often get tricked by mirror reflections on calm lakes (treating the reflected mountains in Moraine Lake as an upside-down cavern rather than a flat horizontal water plane), the self-contained **Three.js + GLSL shader** file below uses **camera-ray unprojection** mapped specifically to this photo’s topography:
- **Horizontal 3D lake plane** (`y > shoreline`) with perspective-correct 3D water ripples and shimmer
- **Foreground left cliff & scree slope** (Tower of Babel side) and **right pine peninsula** in the near/midground
- **Valley of the Ten Peaks & sunset sky** at true background depth

#### How to run it:
1. Save the code below as **`moraine_3d.html`**.
2. Double-click `moraine_3d.html` to open it in any browser, then **drag and drop your image onto the page**.
3. Move your mouse (or drag/scroll) to explore the 3D parallax and dolly into the scene.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Moraine Lake — Interactive 3D Scene</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { background: #070b10; color: #eef2f7; font-family: system-ui, sans-serif; overflow: hidden; }
    canvas { display: block; width: 100vw; height: 100vh; }
    #dropzone {
      position: fixed; inset: 0; display: flex; flex-direction: column;
      align-items: center; justify-content: center; gap: 14px;
      background: radial-gradient(circle at center, #13202cee, #070b10fa);
      z-index: 10; cursor: pointer; transition: opacity 0.4s ease;
    }
    #dropzone.hidden { opacity: 0; pointer-events: none; }
    .card {
      border: 2px dashed #4ea8de88; border-radius: 16px; padding: 40px 56px;
      text-align: center; background: #0d1824aa; backdrop-filter: blur(8px);
    }
    .card h1 { font-size: 1.35rem; margin-bottom: 8px; font-weight: 600; }
    .card p { color: #9db4c8; font-size: 0.95rem; }
    #hud {
      position: fixed; bottom: 18px; left: 50%; transform: translateX(-50%);
      background: #0b131dcc; border: 1px solid #ffffff1f; padding: 8px 18px;
      border-radius: 999px; font-size: 0.82rem; color: #cbd8e6;
      pointer-events: none; opacity: 0; transition: opacity 0.5s;
    }
    #hud.visible { opacity: 1; }
  </style>
</head>
<body>
  <div id="dropzone">
    <div class="card">
      <h1>Drop Your Moraine Lake Photo Here</h1>
      <p>or click anywhere to select the image file</p>
      <input type="file" id="fileInput" accept="image/*" hidden />
    </div>
  </div>
  <div id="hud">Move mouse for 3D parallax • Scroll to dolly in/out • Click & drag to orbit</div>

  <script type="importmap">
    {
      "imports": {
        "three": "https://unpkg.com/three@0.160.0/build/three.module.js"
      }
    }
  </script>

  <script type="module">
    import * as THREE from 'three';

    const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const hud = document.getElementById('hud');

    dropzone.addEventListener('click', () => fileInput.click());
    window.addEventListener('dragover', (e) => e.preventDefault());
    window.addEventListener('drop', (e) => {
      e.preventDefault();
      if (e.dataTransfer.files[0]) loadImage(e.dataTransfer.files[0]);
    });
    fileInput.addEventListener('change', (e) => {
      if (e.target.files[0]) loadImage(e.target.files[0]);
    });

    // Scene & Camera setup
    const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    document.body.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    const FOV = 42;
    const camera = new THREE.PerspectiveCamera(FOV, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 0, -0.35);

    // Build custom continuous depth map tailored to Moraine Lake topology
    function buildDepthTexture(img) {
      const w = 384, h = 256;
      const c = document.createElement('canvas');
      c.width = w; c.height = h;
      const ctx = c.getContext('2d');
      ctx.drawImage(img, 0, 0, w, h);
      const imgData = ctx.getImageData(0, 0, w, h).data;

      const rawDepth = new Float32Array(w * h);

      for (let y = 0; y < h; y++) {
        const v = y / (h - 1); // 0 = top, 1 = bottom
        for (let x = 0; x < w; x++) {
          const u = x / (w - 1); // 0 = left, 1 = right
          const idx = (y * w + x) * 4;
          const r = imgData[idx] / 255, g = imgData[idx + 1] / 255, b = imgData[idx + 2] / 255;

          // Shoreline contour across Moraine Lake
          let vShore = 0.57;
          if (u < 0.36) vShore = 0.63 - (u / 0.36) * 0.06;
          else if (u > 0.59) vShore = 0.57 + ((u - 0.59) / 0.41) * 0.08;

          let dist = 20.0; // Default distant mountains

          if (v > vShore) {
            // Horizontal 3D water plane receding from near camera (D=3.2) to shoreline (D=15)
            const t = (v - vShore) / (1.0 - vShore);
            dist = 1.0 / ((1.0 - t) * (1.0 / 15.0) + t * (1.0 / 3.2));
          } else {
            // Left foreground cliff & scree slope
            const uLeftRidge = 0.085 + v * 0.51;
            // Right pine forest peninsula
            const vRightTrees = 0.57 - Math.max(0, (u - 0.58) / 0.42) * 0.17;

            if (u < uLeftRidge) {
              const cliffT = u / uLeftRidge;
              dist = 4.2 + cliffT * 9.5;
            } else if (u > 0.58 && v > vRightTrees) {
              const forestT = (u - 0.58) / 0.42;
              dist = 14.5 - forestT * 7.5;
            } else {
              // Sky vs Ten Peaks silhouette detection
              const lum = 0.299 * r + 0.587 * g + 0.114 * b;
              const isSky = v < 0.31 && lum > 0.48 && (r > 0.58 || b > 0.52);
              dist = isSky ? 28.0 : 16.5 + (1.0 - v) * 4.5;
            }
          }
          rawDepth[y * w + x] = dist;
        }
      }

      // Smooth depth field (separable box blur passes) so mesh transitions seamlessly
      const temp = new Float32Array(w * h);
      const radius = 6;
      for (let pass = 0; pass < 3; pass++) {
        for (let y = 0; y < h; y++) {
          for (let x = 0; x < w; x++) {
            let sum = 0, cnt = 0;
            for (let k = -radius; k <= radius; k++) {
              const xx = Math.min(w - 1, Math.max(0, x + k));
              sum += rawDepth[y * w + xx]; cnt++;
            }
            temp[y * w + x] = sum / cnt;
          }
        }
        for (let y = 0; y < h; y++) {
          for (let x = 0; x < w; x++) {
            let sum = 0, cnt = 0;
            for (let k = -radius; k <= radius; k++) {
              const yy = Math.min(h - 1, Math.max(0, y + k));
              sum += temp[yy * w + x]; cnt++;
            }
            rawDepth[y * w + x] = sum / cnt;
          }
        }
      }

      return { data: rawDepth, width: w, height: h };
    }

    let mesh = null;
    let uniforms = null;

    function loadImage(file) {
      const url = URL.createObjectURL(file);
      const img = new Image();
      img.onload = () => {
        const colorTex = new THREE.Texture(img);
        colorTex.colorSpace = THREE.SRGBColorSpace;
        colorTex.minFilter = THREE.LinearFilter;
        colorTex.magFilter = THREE.LinearFilter;
        colorTex.needsUpdate = true;

        const depthInfo = buildDepthTexture(img);
        const imgAspect = img.width / img.height;
        const segX = depthInfo.width - 1;
        const segY = depthInfo.height - 1;

        const geom = new THREE.PlaneGeometry(1, 1, segX, segY);
        const pos = geom.attributes.position;
        const uv = geom.attributes.uv;
        const halfH = Math.tan(THREE.MathUtils.degToRad(FOV / 2));

        // Unproject every vertex along its exact optical camera ray from (0,0,0)
        for (let i = 0; i < pos.count; i++) {
          const u = uv.getX(i);
          const v = uv.getY(i); // 1 at top, 0 at bottom
          const gx = Math.round(u * segX);
          const gy = Math.round((1.0 - v) * segY);
          const D = depthInfo.data[gy * depthInfo.width + gx];

          const X = (u - 0.5) * 2.0 * halfH * imgAspect * D;
          const Y = (v - 0.5) * 2.0 * halfH * D;
          const Z = -D;
          pos.setXYZ(i, X, Y, Z);
        }
        geom.computeVertexNormals();

        uniforms = {
          uMap: { value: colorTex },
          uTime: { value: 0 }
        };

        const mat = new THREE.ShaderMaterial({
          uniforms,
          vertexShader: `
            varying vec2 vUv;
            varying float vDist;
            void main() {
              vUv = uv;
              vDist = -position.z;
              gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
          `,
          fragmentShader: `
            uniform sampler2D uMap;
            uniform float uTime;
            varying vec2 vUv;
            varying float vDist;

            void main() {
              vec2 uv = vUv;
              float imgV = 1.0 - uv.y;

              // Shoreline mask for animated 3D lake ripples
              float vShore = 0.57;
              if (uv.x < 0.36) vShore = 0.63 - (uv.x / 0.36) * 0.06;
              else if (uv.x > 0.59) vShore = 0.57 + ((uv.x - 0.59) / 0.41) * 0.08;

              float waterMask = smoothstep(vShore - 0.005, vShore + 0.02, imgV);
              if (waterMask > 0.001) {
                float persp = max(0.025, imgV - vShore);
                float wx = (uv.x - 0.5) / persp;
                float wz = 1.0 / persp;

                float wave1 = sin(wx * 9.0 + uTime * 1.3) * cos(wz * 7.5 - uTime * 1.0);
                float wave2 = sin(wx * 19.0 - uTime * 0.8 + wz * 14.0) * 0.5;
                float ripple = (wave1 + wave2) * waterMask * persp * 0.0065;

                uv.x += ripple;
                uv.y += ripple * 0.55;
              }

              vec4 texColor = texture2D(uMap, clamp(uv, 0.001, 0.999));

              // Subtle golden-hour atmospheric aerial perspective
              float haze = smoothstep(14.0, 30.0, vDist) * 0.045;
              vec3 warmGlow = vec3(1.0, 0.72, 0.58);
              texColor.rgb = mix(texColor.rgb, warmGlow, haze);

              gl_FragColor = texColor;
              #include <colorspace_fragment>
            }
          `
        });

        if (mesh) scene.remove(mesh);
        mesh = new THREE.Mesh(geom, mat);
        scene.add(mesh);

        fitViewport(imgAspect);
        dropzone.classList.add('hidden');
        hud.classList.add('visible');
      };
      img.src = url;
    }

    let baseZ = -0.45;
    function fitViewport(imgAspect = 1.5) {
      const winAspect = window.innerWidth / window.innerHeight;
      camera.aspect = winAspect;
      // Ensure image fills viewport cleanly with headroom for parallax sway
      if (winAspect > imgAspect) {
        const ratio = imgAspect / winAspect;
        camera.fov = THREE.MathUtils.radToDeg(2 * Math.atan(Math.tan(THREE.MathUtils.degToRad(FOV / 2)) * ratio)) * 0.92;
      } else {
        camera.fov = FOV * 0.92;
      }
      camera.updateProjectionMatrix();
    }

    // Smooth interactive parallax & dolly controls
    const target = { x: 0, y: 0, z: baseZ };
    let isDragging = false, prevX = 0, prevY = 0;

    window.addEventListener('pointermove', (e) => {
      const nx = (e.clientX / window.innerWidth - 0.5) * 2;
      const ny = -(e.clientY / window.innerHeight - 0.5) * 2;
      if (isDragging) {
        target.x = THREE.MathUtils.clamp(target.x - (e.clientX - prevX) * 0.003, -0.65, 0.65);
        target.y = THREE.MathUtils.clamp(target.y + (e.clientY - prevY) * 0.003, -0.4, 0.4);
        prevX = e.clientX; prevY = e.clientY;
      } else {
        target.x = nx * 0.38;
        target.y = ny * 0.24;
      }
    });
    window.addEventListener('pointerdown', (e) => { isDragging = true; prevX = e.clientX; prevY = e.clientY; });
    window.addEventListener('pointerup', () => { isDragging = false; });
    window.addEventListener('wheel', (e) => {
      target.z = THREE.MathUtils.clamp(target.z - e.deltaY * 0.0018, -2.4, 0.15);
    }, { passive: true });
    window.addEventListener('resize', () => {
      renderer.setSize(window.innerWidth, window.innerHeight);
      fitViewport();
    });

    const clock = new THREE.Clock();
    function animate() {
      requestAnimationFrame(animate);
      const t = clock.getElapsedTime();
      if (uniforms) uniforms.uTime.value = t;

      camera.position.x += (target.x - camera.position.x) * 0.06;
      camera.position.y += (target.y - camera.position.y) * 0.06;
      camera.position.z += (target.z - camera.position.z) * 0.06;
      camera.lookAt(camera.position.x * 0.25, camera.position.y * 0.25, -12.0);

      renderer.render(scene, camera);
    }
    animate();
  </script>
</body>
</html>
```

